def test_trusted_line_page_ignores_dynamic_row_and_status_colour():
    recognizer = ReferenceScreenRecognizer(REFERENCE_DIR)
    with Image.open(REFERENCE_DIR / "03_line_selection_dialog.png") as source:
        candidate = source.convert("RGB")
        for region in LINE_BUTTON_ROW_REGIONS:
            box = (
                round(candidate.width * region[0]),
                round(candidate.height * region[1]),
                round(candidate.width * region[2]),
                round(candidate.height * region[3]),
            )
            row = candidate.crop(box)
            pixels = row.load()
            for y in range(6, row.height - 6):
                for x in range(8, row.width - 8):
                    red, green, blue = pixels[x, y]
                    if (
                        min(red, green, blue) > 55
                        and max(red, green, blue)
                        - min(red, green, blue)
                        > 25
                    ):
                        pixels[x, y] = (green, blue, red)
            candidate.paste(row, box)

    routes, _points, complete, top, bottom = (
        recognizer._trusted_line_page(candidate)
    )

    assert routes == tuple(range(1, 9))
    assert (complete, top, bottom) == (True, True, True)


