def test_line_button_identity_gate_keeps_measured_true_and_nonbutton_margin():
    recognizer = ReferenceScreenRecognizer(REFERENCE_DIR)
    source = _anonymized_true_line_selection_candidate()
    normalized = recognizer._normalized_line_image(source)
    (
        _route_references,
        identity_references,
        fill_references,
    ) = recognizer._line_signatures_for_source_size(
        source.size
    )

    def identity_score(row):
        signature = recognizer._line_row_button_identity_signature(row)
        return min(
            recognizer._line_row_button_identity_score(
                signature,
                reference_signature,
            )
            for reference_signature in identity_references
        )

    def fill_score(row):
        signature = recognizer._line_row_button_fill_signature(row)
        return min(
            recognizer._line_row_button_fill_score(
                signature,
                reference_signature,
            )
            for reference_signature in fill_references
        )

    true_rows = tuple(
        recognizer._crop(normalized, region)
        for region in LINE_BUTTON_ROW_REGIONS
    )
    true_scores = tuple(identity_score(row) for row in true_rows)
    true_fill_scores = tuple(
        fill_score(row) for row in true_rows
    )
    nearest_nonbutton_score = identity_score(
        source.crop((330, 70, 594, 112)).resize(
            (212, 40),
            Image.Resampling.BILINEAR,
        )
    )
    nearest_nonbutton_fill_score = fill_score(
        source.crop((330, 70, 594, 112)).resize(
            (212, 40),
            Image.Resampling.BILINEAR,
        )
    )

    assert all(
        identity <= LINE_ROW_BUTTON_IDENTITY_MAXIMUM_SCORE
        or (
            fill <= LINE_ROW_BUTTON_FILL_MAXIMUM_SCORE
            and recognizer._line_row_has_button_content(row)
        )
        for row, identity, fill in zip(
            true_rows,
            true_scores,
            true_fill_scores,
            strict=True,
        )
    )
    assert nearest_nonbutton_score >= 0.081
    assert (
        nearest_nonbutton_fill_score
        > LINE_ROW_BUTTON_FILL_MAXIMUM_SCORE
    )
    assert (
        LINE_ROW_BUTTON_IDENTITY_MAXIMUM_SCORE
        < nearest_nonbutton_score
    )


def test_blank_framed_rectangle_cannot_stand_in_for_special_line_button():
    recognizer = ReferenceScreenRecognizer(REFERENCE_DIR)
    candidate = _anonymized_true_line_selection_candidate()
    region = LINE_BUTTON_ROW_REGIONS[1]
    box = (
        round(candidate.width * region[0]),
        round(candidate.height * region[1]),
        round(candidate.width * region[2]),
        round(candidate.height * region[3]),
    )
    row = Image.new(
        "RGB",
        (box[2] - box[0], box[3] - box[1]),
        (29, 88, 111),
    )
    row.paste((255, 255, 255), (2, 2, row.width - 2, 4))
    row.paste(
        (255, 255, 255),
        (2, row.height - 4, row.width - 2, row.height - 2),
    )
    row.paste((255, 255, 255), (2, 2, 4, row.height - 2))
    row.paste(
        (255, 255, 255),
        (row.width - 4, 2, row.width - 2, row.height - 2),
    )
    candidate.paste(row, box)

    trusted = recognizer._trusted_line_page(candidate)
    target = recognizer._line_selection_target(candidate, trusted)

    assert trusted == ((), (), False, False, False)
    assert target[1] is None
    assert target[4] == 0


