def _line_selection_full_window_with_client_top(
    *,
    size: tuple[int, int],
    client_top: int,
) -> Image.Image:
    with Image.open(REFERENCE_DIR / "03_line_selection_dialog.png") as source:
        reference = source.convert("RGB")
    reference_top = round(
        reference.height * LINE_SELECTION_CLIENT_TOP_RATIO
    )
    candidate = Image.new("RGB", size, (16, 16, 16))
    candidate.paste(
        reference.crop((0, 0, reference.width, reference_top)).resize(
            (candidate.width, client_top),
            Image.Resampling.BILINEAR,
        ),
        (0, 0),
    )
    candidate.paste(
        reference.crop(
            (0, reference_top, reference.width, reference.height)
        ).resize(
            (candidate.width, candidate.height - client_top),
            Image.Resampling.BILINEAR,
        ),
        (0, client_top),
    )
    return candidate


