@pytest.mark.parametrize(
    "mutation",
    ("missing-row", "duplicate-row", "order-conflict"),
)
def test_user_live_line_page_mutations_fail_closed_without_input(mutation):
    recognizer = ReferenceScreenRecognizer(REFERENCE_DIR)
    candidate = _anonymized_true_line_selection_candidate()

    def row_box(index):
        region = LINE_BUTTON_ROW_REGIONS[index]
        return (
            round(candidate.width * region[0]),
            round(candidate.height * region[1]),
            round(candidate.width * region[2]),
            round(candidate.height * region[3]),
        )

    if mutation == "missing-row":
        candidate.paste((29, 88, 111), row_box(3))
    elif mutation == "duplicate-row":
        source = candidate.crop(row_box(2))
        target = row_box(3)
        candidate.paste(
            source.resize(
                (target[2] - target[0], target[3] - target[1]),
                Image.Resampling.BILINEAR,
            ),
            target,
        )
    else:
        first_box = row_box(2)
        second_box = row_box(3)
        first = candidate.crop(first_box)
        second = candidate.crop(second_box)
        candidate.paste(
            second.resize(
                (first_box[2] - first_box[0], first_box[3] - first_box[1]),
                Image.Resampling.BILINEAR,
            ),
            first_box,
        )
        candidate.paste(
            first.resize(
                (second_box[2] - second_box[0], second_box[3] - second_box[1]),
                Image.Resampling.BILINEAR,
            ),
            second_box,
        )

    trusted = recognizer._trusted_line_page(candidate)
    target = recognizer._line_selection_target(candidate, trusted)

    assert trusted == ((), (), False, False, False)
    assert target[0] == 2
    assert target[1] is None
    assert target[4] == 0


